// directory_icons (default folder) and chevron_icons.
const directory_collapsed: []const u8 = svg_0001;
const directory_expanded: []const u8 = svg_0002;
const chevron_collapsed: ?[]const u8 = null;
const chevron_expanded: ?[]const u8 = null;

/// The theme's "default" file icon (file_icons["default"]), or null if the theme has none.
pub const default_file: ?[]const u8 = null;

const max_lower_name = 256;

fn lookup(table: []const Entry, key: []const u8) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, table[mid].key, key)) {
            .lt => lo = mid + 1,
            .gt => hi = mid,
            .eq => return table[mid].svg,
        }
    }
    return null;
}

fn findDirectory(name: []const u8) ?DirEntry {
    var lo: usize = 0;
    var hi: usize = named_directories.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, named_directories[mid].key, name)) {
            .lt => lo = mid + 1,
            .gt => hi = mid,
            .eq => return named_directories[mid],
        }
    }
    return null;
}

/// Last path component, accepting both '/' and '\\' separators.
fn baseName(path: []const u8) []const u8 {
    var i = path.len;
    while (i > 0) : (i -= 1) {
        const ch = path[i - 1];
        if (ch == '/' or ch == '\\') return path[i..];
    }
    return path;
}

/// Longest-suffix match: the whole name first, then each suffix after a '.' (left to right).
fn matchSuffix(name: []const u8) ?[]const u8 {
    if (lookup(&file_suffixes, name)) |svg| return svg;
    var rest = name;
    while (std.mem.indexOfScalar(u8, rest, '.')) |dot| {
        rest = rest[dot + 1 ..];
        if (rest.len == 0) break;
        if (lookup(&file_suffixes, rest)) |svg| return svg;
    }
    return null;
}

/// Resolve a file icon for a path or bare file name. Order: exact file_stems entry,
/// longest file_suffixes match (case-sensitive), then the same suffix match on the
/// lowercased name. Returns null when nothing matches.
pub fn fileIcon(path: []const u8) ?[]const u8 {
    const name = baseName(path);
    if (name.len == 0) return null;
    if (lookup(&file_stems, name)) |svg| return svg;
    if (matchSuffix(name)) |svg| return svg;
    var buf: [max_lower_name]u8 = undefined;
    if (name.len > buf.len) return null;
    const lower = std.ascii.lowerString(&buf, name);
    if (std.mem.eql(u8, lower, name)) return null;
    return matchSuffix(lower);
}

/// Icon for a directory by exact name (named_directory_icons), falling back to the
/// default folder icon (directory_icons) for the requested variant.
pub fn directoryIcon(name: []const u8, expanded: bool) []const u8 {
    if (findDirectory(name)) |d| {
        if (expanded) {
            if (d.expanded) |svg| return svg;
        } else {
            if (d.collapsed) |svg| return svg;
        }
    }
    return if (expanded) directory_expanded else directory_collapsed;
}

/// Disclosure chevron. The upstream theme ships none, so this is null for now.
pub fn chevronIcon(expanded: bool) ?[]const u8 {
    return if (expanded) chevron_expanded else chevron_collapsed;
}

test "fileIcon resolves common names" {
    try std.testing.expect(fileIcon("build.zig") != null);
    try std.testing.expect(fileIcon("main.zig") != null);
    try std.testing.expect(fileIcon("README.md") != null);
    try std.testing.expect(fileIcon("src/app/main.zig") != null);
}

test "fileIcon returns null for an unknown extension" {
    try std.testing.expect(fileIcon("notes.zidnonsense") == null);
}

test "directoryIcon falls back to the default folder" {
    try std.testing.expect(directoryIcon("src", false).len > 0);
    try std.testing.expect(directoryIcon("src", true).len > 0);
    try std.testing.expect(directoryIcon("no-such-directory-name", true).len > 0);
}

test "display name has no parenthesised suffix" {
    try std.testing.expect(std.mem.indexOfScalar(u8, display_name, '(') == null);
    try std.testing.expectEqualStrings("Catppuccin Latte", display_name);
    try std.testing.expectEqual(Appearance.light, appearance);
}

test "chevronIcon is null (upstream ships none)" {
    try std.testing.expect(chevronIcon(false) == null);
    try std.testing.expect(chevronIcon(true) == null);
}
